 # A full, readable ledger of all features with a common condition (including non-specific ones).
 l=['# 입력 공통점 전체 목록','',
 '각특징마다실패의절반이상에서관측된조건중일반비실패군대비차이가가장큰한조건을기록한다. 전체컷과비공통조건까지는conditions_with_date_control_v2.csv에있다. 일종의탐색색인이며서로독립인발견들이아니다. q는단일조건전체3328검사보정이며날짜통제q도함께표시한다. 유효표본이전체실패의절반미만인조건은여기에포함하지않지만원CSV에는있다.','']
 for tar,qq in s.groupby('target'):
  total=int(d[(d.target==tar)&d.failure].shape[0]);q=qq[(qq.failure_rate>=.5)&(qq.failure_n>=math.ceil(total/2))].sort_values('lift_matched',ascending=False).drop_duplicates('feature')
  l += [f'## {tar}: {len(q)}개 특징','']
  for rr in q.itertuples():l.append(f'- `{rr.feature}` {rr.operator} {rr.cut:.9g}: 실패 {rr.failure_yes}/{rr.failure_n} ({100*rr.failure_rate:.1f}%), 같은온실×전후반 일반비실패 {100*rr.matched_other_rate:.1f}%, 문제발생 성공 {rr.event_nonfailure_n}일중 {100*rr.event_nonfailure_rate:.1f}%. BH q={rr.q_BH:.3g}, 날짜통제 q={rr.q_fine_date_BH:.3g}. 더큰오차기준빈도 {100*rr.strict2_rate:.1f}%.')
  l+=['']
 p=H/'공통점_전체목록_v1.md';assert not p.exists();p.write_text('\n'.join(l)+'\n',encoding='utf-8')
